<?php require __DIR__.'/../bootstrap.php';admin_only();$orders=$pdo->query('SELECT o.*,u.name user_name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();$title='مدیریت سفارش‌ها';require __DIR__.'/../partials/header.php';?><h1>سفارش‌ها</h1><div class="panel table-wrap"><table class="table"><tr><th>#</th><th>کاربر</th><th>مبلغ</th><th>پرداخت</th><th>وضعیت</th><th>تاریخ</th><th></th></tr><?php foreach($orders as $o): ?><tr><td><?=$o['id']?></td><td><?=e($o['user_name'])?><div class="muted"><?=e($o['email'])?></div></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><span class="badge"><?=e($o['status'])?></span></td><td><?=$o['created_at']?></td><td><a class="btn small" href="<?=url('admin/order.php?id='.$o['id'])?>">مدیریت</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
